  const stack = [];
  let answer = 0;
  for (const value of nums) {
    let steps = 0;
    while (stack.length > 0 && stack[stack.length - 1][0] <= value) {
      steps = Math.max(steps, stack.pop()[1]);
    }
    steps = stack.length > 0 ? steps + 1 : 0;
    answer = Math.max(answer, steps);
    stack.push([value, steps]);
  }
  return answer;
}

