function totalSteps(nums) {
  // Simulate the steps literally until nothing is deleted.
  let current = nums.slice();
  let count = 0;
  for (;;) {
    const kept = current.filter((v, i) => i === 0 || current[i - 1] <= v);
    if (kept.length === current.length) return count;
    current = kept;
    count++;
  }
}

