function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1500 + pick(501) : 1 + pick(10);
  const mode = pick(4);
  if (mode === 0) {
    // Small values: many equal neighbours and short descents.
    const top = size === 'large' ? 50 : 1 + pick(6);
    return [Array.from({ length: n }, () => 1 + pick(top))];
  }
  if (mode === 1) {
    // Wide random values.
    return [Array.from({ length: n }, () => 1 + pick(1000000000))];
  }
  // Blocks that start high and then rise slowly, which makes long chains of deletions.
  const nums = [];
  let high = 1000000000;
  while (nums.length < n) {
    const block = 1 + pick(Math.min(n - nums.length, size === 'large' ? 600 : 6));
    nums.push(high);
    let low = 1 + pick(1000);
    for (let i = 1; i < block; i++) {
      low += pick(3);
      nums.push(mode === 2 ? low : 1 + pick(low + 5));
    }
    high -= pick(high > 2000 ? 1000 : 1);
  }
  return [nums];
}
